def variants(shape):
 out=[]
 for refl in [False,True]:
  for rot in range(4):
   pts=[]
   for r,c in shape:
    if refl:c=-c
    for _ in range(rot):r,c=c,-r
    pts.append((r,c))
   mr=min(r for r,c in pts); mc=min(c for r,c in pts)
   norm=frozenset((r-mr,c-mc) for r,c in pts)
   if norm not in out:out.append(norm)
 return out
